package org.example.islamicapp.feature.learn.data

import org.example.islamicapp.feature.learn.domain.LearnStep
import org.example.islamicapp.feature.learn.domain.LearnTopic
import javax.inject.Inject
import javax.inject.Singleton

/**
 * Stories of all 25 prophets mentioned in the Qur'an (طلب الإضافة) —
 * each story from the Qur'anic account with its lesson, in Arabic and
 * English, presented for all ages.
 */
@Singleton
class ProphetsStoriesRepository @Inject constructor() {

    val topic: LearnTopic by lazy {
        LearnTopic(
            id = "prophets_stories",
            titleAr = "قصص الأنبياء — النبيون الخمسة والعشرون",
            titleEn = "Stories of the Prophets — all 25 in the Qur'an",
            steps = listOf(
                step("آدم عليه السلام", "Adam",
                    "أول البشر: خلقه الله بيده ونفخ فيه من روحه وأسجد له ملائكته، وأسكنه وزوجه الجنة، فأزلهما الشيطان بالوسوسة عنها فهبطا إلى الأرض توبةً وطلبًا لرزق واختبار.وتلقى آدم من ربه كلمات فتاب عليه.وقصته تعلّم أن الخطر في الغرور والعدو المتربص، وأن باب التوبة مفتوح، وأن الإنسان خُلق لأمانة الأرض لا لراحة الجنة: ﴿وَإِذْ قَالَ رَبُّكَ لِلْمَلَائِكَةِ إِنِّي جَاعِلٌ فِي الْأَرْضِ خَلِيفَةً﴾ [البقرة: 30].",
                    "The first human: created by Allah's own hand, honored above the angels, dwelling in Paradise until Satan's whisper caused the descent to earth — with repentance accepted. His story teaches the danger of pride and the enemy's ambush, that repentance's door is open, and that humanity was created for the trust of earth, not the rest of Paradise (2:30)."),
                step("إدريس عليه السلام", "Enoch (Idris)",
                    "﴿وَاذْكُرْ فِي الْكِتَابِ إِدْرِيسَ إِنَّهُ كَانَ صِدِّيقًا نَّبِيًّا ۝ وَرَفَعْنَاهُ مَكَانًا عَلِيًّا﴾ [مريم: 56-57].كان صديقًا نبيًا رفعه الله مكانًا عليًا؛ قيل: أول من خط بالقلم وعلم النجوم والحساب فيما رُوي.وعبرته: صدق المنزلة يرفع صاحبه عند الله وإن خفي على الناس.",
                    "'And mention Idris in the Book; he was a truthful prophet, and We raised him to a high station' (19:56-57). Tradition holds he was among the first to write and observe the stars. His lesson: truthfulness raises one with Allah even if unknown to people."),
                step("نوح عليه السلام", "Noah",
                    "أول الرسل إلى أهل الأرض بعد انتشار الشرك؛ دعا قومه ٩٥٠ سنة ﴿فَلَنْ أَدْعُوَ النَّاسَ إِلَىٰ عَذَابِ اللَّهِ﴾ سرًّا وجهرًا فما زادهم دعاؤه إلا فرارًا، وقالوا مسخرين: أنؤمن لك واتبعك الأرذلون؟ فبأمر الله بنى الفلك وهم يسخرون، فجاء أمر الله وفار التنور فحمل فيها من كل زوجين اثنين وأهله إلا من سبق عليه القول ومن آمن، وغرّقت الأرض كلها.ونادى ابنه: يا بني اركب معنا ولا تكن مع الكافرين — فقال: سآوي إلى جبل يعصمني من الماء — فحال بينهما الموج فكان من المغرقين.وقبلها دعا: رب إن ابني من أهلي وإن وعدك الحق؛ فقيل: إنه ليس من أهلك إنه عمل غير صالح.فعلم أن الرحم لا تنفع بلا إيمان، ثم قال: رب إني أعوذ بك أن أسألك ما ليس لي به علم.وبعث الله الناس كلهم من نسل من نجا: ﴿وَجَعَلْنَا ذُرِّيَّتَهُ هُمُ الْبَاقِينَ﴾ [الصافات: 77].",
                    "The first messenger to a world drowned in idolatry; he preached 950 years — mocked for his followers being 'the lowliest'. By God's command he built the ark amid ridicule; the flood came and carried believers and the pairs of creatures while earth's defiant were drowned. His own son trusted the mountain over the ark — 'he is not of your family; his deed was unrighteous' — teaching that blood avails nothing without faith, and that all humanity descends from those saved."),
                step("هود عليه السلام", "Hud",
                    "أُرسل إلى عاد بالأحقاف — قوم جبابرة بنوا بأيديهم مصاعف وبيوتًا في الجبال وقالوا: من أشد منا قوة؟ — فقال لهم أخوهم هود: يا قوم اعبدوا الله ما لكم من إله غيره إن أنتم إلا تفترون... وأطيعوا أمر ربكم من قبل أن يأتيكم عذاب مما لا يرد.فأخذتهم الرجفة بريح صرصر عاتية أهلكتهم ﴿فَأَصْبَحُوا لَا يُرَىٰ إِلَّا مَسَاكِنُهُمْ﴾ [الأحقاف: 25].وعبرتها: القوة الحقيقية ليست في الأجساد والحضارة بل في الإيمان؛ وجبروت البشر ذرة أمام قدرة الله.",
                    "Sent to Ad of the dunes — giants boasting 'who is stronger than us?' Their brother Hud called to the One God; they refused, and a furious barren wind slew them till only their dwellings remained (46:25). Lesson: true strength is faith; human might is an atom before God's power."),
                step("صالح عليه السلام", "Salih",
                    "أُرسل إلى ثمود الذين ورثوا الأرض بعد عاد فاعتدوا وبغوا، فأتاهم بالناقة آية: لها شرب ولكم شرب يوم معلوم؛ فقال لهم: هذا ناقة الله فلا تسوؤها فأخذوها وهم آمنون ثم عقرها أشقاكم — وقد تواعدوا قبلها: قال من أنذركم؟ فلما عقروا قال: تمتعوا في داركم ثلاثة أيام.فأخذتهم الصيحة والرجفة فأصبحوا في ديارهم جاثمين.وعبرتها: آيات الله ليست مواد امتحان للعناد؛ ومكيدة الجماعة لا تنجيهم من الأخذ، وشؤم المعاصي يعم.",
                    "Sent to Thamud, heirs of Ad; the she-camel was his sign — her watering day versus theirs. Their most wretched one hamstrung her after the plotters' pact, so three days' respite ended in the Cry that left them fallen in their homes. Lesson: God's signs are not to be tested with defiance; collective scheming shares collective ruin."),
                step("إبراهيم عليه السلام — خليل الرحمن", "Abraham, the intimate friend",
                    "أبو الأنبياء: حاجّ قومه بالحق وهو فتى: قال هذا ربي النجم... هذا ربي القمر... هذا ربي الشمس... يا قوم إني بريء مما تشركون، إني وجهت وجهي للذي فطر السماوات والأرض حنيفًا.فكسّر أصنامهم إلا كبيرًا وعلق الفأس برقبته فقالوا: من فعل هذا بآلهتنا؟ فألقاها على الكبير: بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون — فرجعوا إلى أنفسهم ثم نكسوا على رؤوسهم.فحرقوه فجعل الله النار بردًا وسلامًا.وهاجر إلى الشام ومعه لوط، وامرأته سارة عقيما فوهبها الله إسحاق على الكبر، ووهب هاجر إسماعيل، وأمره الله أن يضع هاجر وإسماعيل بمكة بوادٍ غير ذي زرع فقالت رضاً بالله: آلله أمرك بهذا؟ قال: نعم؛ قالت: إذن لا يضيعنا.وابتُلي بذبح إسماعيل فقال يا بني إني أرى في المنام أني أذبحك؛ قال: يا أبت افعل ما تؤمر ستجدني إن شاء الله من الصابرين — ففداه الله بكبش عظيم: ﴿وَفَدَيْنَاهُ بِذِبْحٍ عَظِيمٍ﴾ [الصافات: 107].ورفع القواعد من البيت مع إسماعيل: ربنا تقبل منا إنك أنت السميع العليم.ودعا: ربنا وابعث فيهم رسولًا منهم — فكان محمد ﷺ من ذريته إجابةً لدعوته.وجعل الله في ذريته النبوة والكتاب؛ فكل أنبياء بني إسرائيل من إسحاق وكل عرب الحجاز من إسماعيل.",
                    "Father of prophets: as a youth he debated the star, moon and sun worshippers — 'I turn my face to Him who created the heavens and earth.' He smashed the idols, hung the axe on the chief's neck, and shamed the priests with their own logic; the fire became cool and safe by God's word. Exiled with Hajar and Ishmael to the barren valley of Mecca — 'Was it God's command?' 'Yes.' 'Then He will not abandon us.' Tested with the sacrifice of his son, both submitted; a great ram ransomed him. With Ishmael he raised the Ka'bah's foundations and prayed for a messenger from his line — answered fourteen centuries later by Muhammad ﷺ. Prophethood and scripture flowed through both his sons."),
                step("لوط عليه السلام", "Lot",
                    "ابن أخي إبراهيم؛ أُرسل إلى سدوم وأعمالها على قوم أتوا فاحشة ما سبقهم بها أحد من العالمين، فقال لهم ألا تتقون؟ أئنكم لتأتون الذكران من العالمين وتذرون ما خلق لكم ربكم من أزواجكم؟ بل أنتم قوم عادون.وما كان جوابهم إلا أن قالوا أخرجوا آل لوط من قريتكم إنهم أناس يتطهرون — فحسدوهم على الطهارة!فجاءته الملائكة في صورة رجال ضيوفًا لإبراهيم ثم إلى لوط، ولما ضاق بهم ذرعًا وقيل له يا لوط إنا رسل ربك لن يصلوا إليك؛ فأسرو بأهله بقطع من الليل ولا يلتفت منكم أحد إلا امرأتك، وجاء أمر الله فجعل الله عاليها سافلها وأمطر عليهم حجارة من سجيل منضود.وعبرتها: إفساد المجتمع إذا استعلن وارتضاه أهله يستنزل هلاكًا عميمًا، والنجاة للطهارة والاتباع لا لمجرد الأنساب — فامرأته هلكت بحسابها.",
                    "Abraham's nephew sent to Sodom, whose people pioneered an abomination none before them did. His rebuke met the answer: 'Expel Lot's family — they purify themselves!' — envying purity itself. The angels arrived as guests; 'O Lot, we are messengers of your Lord; they cannot reach you.' The city was overturned and stoned. Lesson: a society that celebrates corruption invites collective ruin; salvation is for purity and obedience, not lineage — even Lot's wife perished."),
                step("إسماعيل عليه السلام", "Ishmael",
                    "الابن البكر الذبيح الصابر: قال الله عنه: ﴿فَبَشَّرْنَاهُ بِغُلَامٍ حَلِيمٍ﴾ [الصافات: 101] — فلما بلغ معه السعي قال يا أبتِ... وقال عنه القرآن: ﴿إِنَّهُ كَانَ صَادِقَ الْوَعْدِ وَكَانَ رَسُولًا نَّبِيًّا﴾ [مريم: 54].سقى أمه زمزم نبتت تحت قدميه، وشب في مكة وتعلم العربية من جرهم وتزوج منهم، وأعان أباه في بناء الكعبة: يا أبتِ افعل ما تؤمر.وأمره الله أن يقيم في الوادي الجاف حول البيت الحرام فأقام وذريته إلى اليوم، وبقي النداء: ﴿وَأَذِّن فِي النَّاسِ بِالْحَجِّ﴾ يستجاب له من كل فج عميق — من نسل إسماعيل جاء خاتم النبيين ﷺ.",
                    "The patient son ready for sacrifice — 'We gave him glad tidings of a forbearing boy'; 'he was true to his promise, a messenger-prophet' (19:54). Zamzam sprang for his mother; he grew in Mecca, learned Arabic, helped raise the Ka'bah with his father, and settled his seed around the Sacred House. From his line came the final Prophet ﷺ, and the call to Hajj established with Abraham still answers from every deep ravine."),
                step("إسحاق عليه السلام", "Isaac",
                    "البشارة الثانية لإبراهيم من سارة العجوز العقيم: ﴿فَبَشَّرْنَاهَا بِإِسْحَاقَ وَمِن وَرَاءِ إِسْحَاقَ يَعْقُوبَ﴾ [هود: 71] — فضحكت المرأة العجوز عجبًا من وعد الله الذي لا تعجزه العادة.﴿وَبَشَّرْنَاهُ بِإِسْحَاقَ نَبِيًّا مِّنَ الصَّالِحِينَ وَبَارَكْنَا عَلَيْهِ وَعَلَىٰ إِسْحَاقَ﴾ — وقال النبي ﷺ: «الكريم ابن الكريم ابن الكريم ابن الكريم: يوسف بن يعقوب بن إسحاق بن إبراهيم» [رواه البخاري].من ذريته كل أنبياء بني إسرائيل.",
                    "The second glad tiding — to aged, barren Sarah: 'Isaac, and after Isaac, Jacob' (11:71). The Qur'an names him a righteous prophet, blessed with his father. The Prophet ﷺ called his line 'the generous son of the generous, four times' (Bukhari). From Isaac descended all the prophets of Israel."),
                step("يعقوب (إسرائيل) عليه السلام", "Jacob (Israel)",
                    "نبي صابر؛ جُعل في قصته مع أبنائه أسوة الصبر الجميل: حسده أبناؤه على حبه ليوسف فألقوه في الجب وجاؤوا أباهم عشاءً يبكون بقميص ملطخ بدم كذب؛ فقال: ﴿بَلْ سَوَّلَتْ لَكُمْ أَنفُسُكُمْ أَمْرًا ۖ فَصَبْرٌ جَمِيلٌ﴾ [يوسف: 18]، ولما فارقه الثاني قال: ﴿فَصَبْرٌ جَمِيلٌ عَسَى اللَّهُ أَن يَأْتِيَنِي بِهِمْ جَمِيعًا﴾ — فأراه الله جميعًا بمصر وأدخله عليهم وقال: ﴿سَوْفَ أَسْتَغْفِرُ رَبِّي﴾، وأوصى بنيه في الموت: ﴿فَلَا تَمُوتُنَّ إِلَّا وَأَنتُم مُّسْلِمُونَ﴾ [البقرة: 132].وأولاده الأسباط أبوا الشعوب الاثني عشر؛ منه تفرق بنو إسرائيل.",
                    "The prophet of beautiful patience: deceived by his own sons with Joseph's bloodied shirt — 'patience most fair'; when the second son was kept, 'perhaps Allah will bring them all to me' — and He did, in Egypt. On his deathbed he charged his children: 'Die not except in submission' (2:132). His twelve sons fathered Israel's twelve tribes."),
                step("يوسف عليه السلام — صدق الرؤيا", "Joseph",
                    "رؤيا الصبا: أحد عشر كوكبًا والشمس والقمر له ساجدين؛ فأولها أبوه: لا تقصص رؤياك على إخوتك.فحسده أخوته: ليوسف وأخوه أحب إلى أبينا منا ونحن عصبة؟ — فألقي في الجب، وباعه السيارة بثمن بخس دراهم معدودة، واشتراه عزيز مصر: أكرمي مثواه.وامتُحن بمراودة امرأة العزيز فقال معاذ الله: إنه ربي أحسن مثواي؛ إن النساء ليصدقن من حسن ما دعا — وشهد شاهد من أهلها فبرأه الله، ثم قال بعدما رأى برهان ربه: رب السجن أحب إليّ مما يدعونني إليه.وسُجن بلا جريرة ثم فسر رؤيا الملك: سبع سنوات خصب ثم سبع شداد ثم عام يغاث فيه الناس — فقال اجعلني على خزائن الأرض إني حفيظ عليم، فأدار أزمة الجوع بيقين الله وتخطيطه.وجاءه أخوته فعدل عنهم وعزّزهم وغيّر مكرهم في دبرهم، ثم أدار وجهه عنهم: هل علمتم ما فعلتم بيوسف؟ قالوا: أإنك لأنت يوسف؟ قال: أنا يوسف وهذا أخي قد منّ الله علينا؛ إنه من يتقّ ويصبر فإن الله لا يضيع أجر المحسنين.قالوا: تالله لقد آثرك الله علينا؛ قال: لا تثريب عليكم اليوم يغفر الله لكم — فجمع العفو بالفضل.وألبس أبوه القميص فارتد بصيرًا، ودخلوا عليه خضعًا فقال: يا أبتِ هذا تأويل رؤياي من قبل قد جعلها ربي حقًّا.خاتمته: ﴿رَبِّ قَدْ آتَيْتَنِي مِنَ الْمُلْكِ وَعَلَّمْتَنِي مِن تَأْوِيلِ الْأَحَادِيثِ…تَوَفَّنِي مُسْلِمًا وَأَلْحِقْنِي بِالصَّالِحِينَ﴾ [يوسف: 101].قال ﷺ عن سورته: «إن أشرف القصص قصة يوسف» — عبرة الصبر على القدر والنجاة بالعفة وأن عاقبة التقوى جميلة.",
                    "The boy dreamt eleven stars, sun and moon prostrating. Envied, thrown in a well, sold for a few coins, purchased by Egypt's minister — then tempted by his master's wife: 'God forbid; he honoured my dwelling.' He chose prison over sin, interpreted the king's dream, administered Egypt's famine plan, and finally revealed himself to his brothers: 'No blame on you today; may Allah forgive you' — forgiving with grace. The shirt restored his father's sight; the childhood dream came true. His prayer closes the noblest story: 'Cause me to die a Muslim and join me with the righteous' (12:101)."),
                step("أيوب عليه السلام — الصابر", "Job",
                    "﴿وَأَيُّوبَ إِذْ نَادَىٰ رَبَّهُ أَنِّي مَسَّنِيَ الضُّرُّ وَأَنتَ أَرْحَمُ الرَّاحِمِينَ﴾ [الأنبياء: 83].امتُحن في ماله وأهله وجسده سنين طويلة حتى أعرض عنه جلساؤه وما بقي له إلا زوجته تخدمه وتقوم عليه، وما سأل الله كشفًا لنفسه اشتدادًا حتى لاحظ دابة تدفن في الرمل مشفقة عليها من عطشها فقال: لو كان لي ما أقدر به على سقيها سقيتها؛ فشكر الله له ذلك وأعاده الله كما كان وأتاه أهله ومثلهم معهم رحمةً وذكرى للعابدين: اركض برجلك هذا مغتسل بارد وشراب.وعبرته: البلاء ليس دليل سخط، والصبر مع العمل والرحمة بالخلق مفتاح الفرج، وأن الله يخلف الصابرين أحسن مما كانوا.",
                    "'And Job called his Lord: affliction has touched me, and You are the Most Merciful' (21:83). Wealth, family and health were tested for years; he asked nothing until his heart pitied a thirsty beast — 'had I the means I would water her.' Allah restored him doubled, with a spring and his family. Lesson: affliction is not wrath; mercy to creatures plus patience unlocks relief, and Allah compensates beyond measure."),
                step("ذو الكفل عليه السلام", "Dhul-Kifl",
                    "﴿وَإِسْمَاعِيلَ وَإِدْرِيسَ وَذَا الْكِفْلِ كُلٌّ مِّنَ الصَّابِرِينَ﴾ [الأنبياء: 85].ذُكر مقرونًا بالصابرين الصالحين؛ قال المفسرون: سُمّي ذا الكفل لأنه تكفّل بأمرٍ فوفى به — قيل: قام مقام نبيّ في قومه ليصوم النهار ويقوم الليل ولا يغضب، فصدق الله فيه.وعبرته: شرف الوفاء بالعهد والصبر على التكفل بالمسؤولية، وأن الالتزام الكامل عبادة.",
                    "Named with the patient and righteous (21:85); the commentators say he was called 'Dhul-Kifl' for undertaking a charge and fulfilling it — standing in a prophet's place with fasting, night prayer and restrained anger. Lesson: honouring commitments is itself worship."),
                step("شعيب عليه السلام — خطيب الأنبياء", "Jethro (Shu'ayb)",
                    "أُرسل إلى مدين قوم يعبدون الأيكة ويبخسون المكيال والميزان: يا قوم اعبدوا الله ما لكم من إله غيره ولا تنقصوا المكيال والميزان إني أراكم بخير وإني أخاف عليكم عذاب يوم محيط... بقيّت الله خير لكم إن كنتم مؤمنين.فقالوا مستهزئين: يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء؟ — فردّ عليهم المنطق: وما أريد أن أخالفكم إلى ما أنهاكم عنه.فأخذتهم الرجفة فأصبحوا في دارهم جاثمين.وعبرته: الاقتصاد أخلاقي قبل أن يكون رقميًّا؛ وأكل حقوق الناس بالبخس جريمة تهلك المجتمعات، والصدق في المعاملة من الإيمان.",
                    "Sent to Madyan, worshippers of the thicket who cheated scales: 'Worship God; diminish not measure — what remains by God's right is better for you.' They sneered: 'Does your prayer command us to abandon our fathers' ways?' He answered: 'I do not wish to oppose you to what I forbid you.' The quake took them. Lesson: honest dealing is faith in action; economic cheating destroys societies."),
                step("موسى عليه السلام — كليم الله", "Moses, the one spoken to",
                    "وُلد في عام ذبح الفراعنة الأطفال، فأوحى الله لأمه: ألقيه في التابوت فاقذفيه في اليمّ ولا تخافي ولا تحزني إنا رادّوه إليك وجاعلوه من المرسلين — فالتقطه آل فرعون ليكون لهم عدوًّا وحزنًا.وربّاه الله في قصر عدوه وردّه إلى أمه كي تقرّ عينها.ولما قتل المصري خطئًا خرج خائفًا يترقب إلى مدين فسقى لامرأتين ضعيفتين ثم تزوج إحداهما، وأوحى الله له من الشجرة المباركة: إنني أنا الله لا إله إلا أنا فاعبدني وأقم الصلاة لذكري؛ اذهب إلى فرعون إنه طغى.فقال: رب اشرح لي صدري ويسّر لي أمري واحلل عقدة من لساني يفقهوا قولي؛ قال: قد أوتيت سؤلك يا موسى.ودخل مع أخيه هارون على أعظم طاغية في الأرض: فقولا له قولًا لينًا لعله يتذكر أو يخشى — فقال فرعون: ما رب العالمين؟ وتحدّاه بعصيه فألقى موسى عصاه فإذا هي ثعبان مبين ونزع يده فإذا هي بيضاء للناظرين، فجمع السحرة من كل فج، فألوا فسحروا أعين الناس؛ فألقى موسى عصاه فإذا هي تلقف ما يأفكون؛ فألقى السحرة ساجدين: آمنا برب هارون وموسى؛ ما تريد أن نؤمن لك بما جاءنا من البينات وربنا خلقنا فقال فرعون: لأقطعن أيديكم وأرجلكم من خلاف؛ قالوا: لن نؤثرك على ما جاءنا من البينات فاقض ما أنت قاض.ثم أتبعهم الله بالسنون ونقص من الثمرات والطوفان والجراد والقمّل والضفادع والدم آيات مفصّلات فاستكبروا.وأوحى الله لموسى أن يسري بعباده ليلًا فأتبعهم فرعون بجنوده حتى تراءى الجمعان عند البحر: قال أصحاب موسى إنا لمدركون؛ قال: كلا إن معي ربي سيهدين؛ فضرب البحر بعصاه فانفلق اثني عشر طريقًا ونجا بنو إسرائيل وغرق فرعون فيما ادعى أنه رب: ﴿فَالْيَوْمَ نُنَجِّيكَ بِبَدَنِكَ لِتَكُونَ لِمَنْ خَلْفَكَ آيَةً﴾ [يونس: 92].ثم التوراة والألواح وجبل الطور وميقات ربه أربعين ليلة، وعبادة القوم للعجل في غيبته بفعل السامري فتاب الله عليهم، ومنّ عليهم بالمنّ والسلوى وعيون الحجر، وما علمه الخضر من الحكمة الخفية: إنك لن تستطيع معي صبرًا... وكيف تصبر على ما لم تحط به خبرًا — ثلاث حوادث ظاهرها الشر وباطنها الرحمة.وعبر موسى عليه السلام أمةً وحده على من دونه، وكُلم الله تكليمًا.",
                    "Born under Pharaoh's slaughter decree; the river carried him to the tyrant's own palace to be raised as family — Allah's plan against their plan. Called from the burning bush: 'Go to Pharaoh; he has transgressed.' With 'speak gently' as strategy, Moses and Aaron confronted him; staff swallowed the magicians' illusions, and the magicians believed under threat of mutilation. Ten signs followed; then the night exodus and the sea splitting — twelve dry paths, Pharaoh drowned as a sign for posterity. The Torah at the mountain, the calf's apostasy and repentance, manna and quail, and al-Khidr's lessons in hidden mercy. He remains the most-mentioned prophet in the Qur'an, spoken to by God."),
                step("هارون عليه السلام", "Aaron",
                    "شريك أخيه في الرسالة وسنده: ﴿وَأَخِي هَارُونُ هُوَ أَفْصَحُ مِنِّي لِسَانًا فَأَرْسِلْهُ مَعِيَ رِدْءًا يُصَدِّقُنِي﴾ [القصص: 34] — وزيرًا معينًا.وقال الله: ﴿وَلَقَدْ مَنَنَّا عَلَىٰ مُوسَىٰ وَهَارُونَ…وَآتَيْنَاهُمَا الْكِتَابَ الْمُسْتَبِينَ﴾ [الصافات: 114-117].حفظ قومه في غياب موسى لكنهم أُكرهوا على العجل: ﴿إِنَّ الْقَوْمَ تَغَلَّبُوا عَلَيَّ﴾ [طه: 87]، وعبرته: الوزارة الصادقة والفصاحة في الحق نعمة يُسأل عنها صاحبها، وأن الضعف أمام الفتنة الجماعية مغفور بالصدق والأخذ على اليد.",
                    "Partner in prophethood and his brother's support: 'my brother Aaron is more eloquent — send him with me to confirm me' (28:34). Given the clear scripture with Moses; he restrained the people over the calf though overwhelmed. Lesson: eloquence and true deputyship are trusts; being overpowered in mass trial is pardoned through truthfulness."),
                step("داود عليه السلام", "David",
                    "فتىٌ في جيش طالوت بركب الجالوت فرده الله بداود: فقتله داود وآتاه الله الملك والحكومة: ﴿وَقَتَلَ دَاوُودُ جَالُوتَ وَآتَاهُ اللَّهُ الْمُلْكَ وَالْحِكْمَةَ وَعَلَّمَهُ مِمَّا يَشَاءُ﴾ [البقرة: 251].أُنزل عليه الزبور وأُلان له الحديد وأُوتي الصوت العجيب: ﴿وَإِنَّ مِنَ الْجِبَالِ لَهُ سُبُلًا… مَعَ الطَّيْرِ﴾ — تسبّح الجبال والطير معه إدراكًا.وحُكم الخصمين المتسورين المحراب ففهم القصة بواحدة: ففهمها داود فولى إلى الله مستغفرًا فغفر الله له.وعبرته: الجمع بين الملك والعبودية؛ والفتوى والقضاء مسؤولية تفصل بالوحي لا بالوجاهة، والتسبيح قلب العمل.",
                    "The youth in Saul's army felled Goliath, and Allah gave him kingship and wisdom (2:251). The Psalms were revealed; iron was softened for him; mountains and birds joined his praise. Judging the two disputants who scaled his sanctuary, he grasped the case instantly and turned to Allah in repentance. Lesson: authority with servitude; judgement is a fearful trust; praise of God is the heart of deed."),
                step("سليمان عليه السلام", "Solomon",
                    "ورث داود نبأً وملكًا: ﴿وَوَرِثَ سُلَيْمَانُ دَاوُودَ ۖ وَقَالَ يَا أَيُّهَا النَّاسُ عُلِّمْنَا مَنطِقَ الطَّيْرِ﴾ [النمل: 16].ملك لا ينبغي لأحد من بعده: تسخير الريح غدوّها شهر ورواحها شهر، والشياطين البنائين والغواصين، والنملة الدابة الضعيفة نادت قومها: لا تحطمنكم سليمان وجنوده وهم لا يشعرون — فتبسم ضاحكًا من قولها وقال: رب أوزعني أن أشكر نعمتك.وعرض عليه عرش بلقيس ملكة سبأ: قال هذا عطاء ربي، وقيل له: هذا ملكي الذي أُعطيت؟ فقال: هذا من فضل ربي ليبلوني أأشكر أم أكفر — والملك عنده أصغر من الشكر.ودخلت بلقيس في الإسلام لما رأت ما رأت: رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين.وخاتمته: ملك كل شيء ثم قال: ﴿رَبِّ أَوْزِعْنِي أَنْ أَشْكُرَ نِعْمَتَكَ الَّتِي أَنْعَمْتَ عَلَيَّ وَعَلَىٰ وَالِدَيَّ﴾ [النمل: 19].وعبرته: الملك الحقيقي ملك الشكر لا ملك الريح؛ وأن أعظم النعم أن يُسخّر الله لك ما لا تملك.",
                    "He inherited David's prophethood and kingdom and was taught the speech of birds (27:16). A dominion unique in history: month-journey winds, building and diving jinn — and an ant's warning that made him smile: 'My Lord, enable me to thank Your blessing.' Queen Bilqis' throne was fetched in the blink of an eye; he called it a trial, not a trophy — 'this is by my Lord's favour to test whether I am grateful.' The queen submitted. Lesson: real kingship is gratitude; the greatest gift is God's harnessing for you what you could never own."),
                step("إلياس عليه السلام", "Elijah",
                    "﴿وَإِنَّ إِلْيَاسَ لَمِنَ الْمُرْسَلِينَ… سَلَامٌ عَلَىٰ إِلْ يَاسِينَ﴾ [الصافات: 123، 130].دعا قومه على عبادة بعل: ألا تتقون؟ أتدعون بعلاً وتذرون أحسن الخالقين؟ فكذّبوه؛ فقال: سيرفعني الله إليه ويعاقبهم.فأُرسل عليهم العذاب، ونجا هو ومن اتبعه.وعبرته: الصمود في مواجهة عبادة الأهواء الجماعية، وأن الله يرفع رسله ولو خذلهم الناس.",
                    "'Elias was surely of the messengers... peace be upon the family of Yasin' (37:123,130). He challenged Baal worship: 'Do you call on Baal and abandon the best of creators?' They denied; punishment came while he and his followers were honoured. Lesson: standing alone against mass falsehood; God elevates His messengers though people forsake them."),
                step("اليسع عليه السلام", "Elisha",
                    "﴿وَإِسْمَاعِيلَ وَالْيَسَعَ وَيُونُسَ وَلُوطٌ ۖ وَكُلًّا فَضَّلْنَا عَلَى الْعَالَمِينَ﴾ [الأنعام: 86].خلف إلياس في بني إسرائيل؛ مدحه الله بالتفضيل على العالمين، وذكره النبي ﷺ في حقٍّ روي في قصص الأنبياء أنه عاش رفيقًا إلياس في سفره وخدمته فورث علمه ونبوته.وعبرته: بركة صحبة الصالحين؛ وخدمة العلماء طريق لورثة النبوة: العلماء ورثة الأنبياء.",
                    "Named with those preferred over all worlds (6:86); he succeeded Elijah among Israel. Tradition honours his companionship and service to Elijah, inheriting his knowledge. Lesson: blessedness of keeping righteous company; serving scholars opens the inheritance of prophetic knowledge."),
                step("يونس عليه السلام — ذو النون", "Jonah",
                    "غضب لقومه حين عصوا وخرج قبل أن يأذن الله له: ﴿وَذَا النُّونِ إِذ ذَّهَبَ مُغَاضِبًا فَظَنَّ أَن لَّن نَّقْدِرَ عَلَيْهِ﴾ [الأنبياء: 87]، فتسّنم في الفلك المشحون فساهم فكان من المدحضين فالتقمه الحوت وهو مليم.﴿فَنَادَىٰ فِي الظُّلُمَاتِ أَن لَّا إِلَٰهَ إِلَّا أَنتَ سُبْحَانَكَ إِنِّي كُنتُ مِنَ الظَّالِمِينَ﴾ [الأنبياء: 87] — فقال الله: ﴿فَاسْتَجَبْنَا لَهُ وَنَجَّيْنَاهُ مِنَ الْغَمِّ ۚ وَكَذَٰلِكَ نُنجِي الْمُؤْمِنِينَ﴾ — قال ﷺ: «دعوة ذي النون... لم يدعُ بها رجل مسلم في شيء قط إلا استجاب الله له» [رواه الترمذي].ونُبذ بالعراء وهو سقيم وأنبت عليه شجرة من يقطين، وأرسله الله إلى قومه فآمن به مئة ألف أو يزيدون فمتعناهم إلى حين.وعبرته: كلمة التوحيد في أشد الظلمات تفتح أبواب السماء؛ ولا يأس من رحمة الله مهما عظم الخطأ، وأن الخروج من مسؤولية الدعوة بلا إذن الله بلاء.",
                    "He left in anger before God's leave, drew lots on the laden ship, and the whale swallowed him — blameful. Then from the three darknesses: 'There is no god but You; glory to You; I was of the wrongdoers' (21:87) — 'Thus We save the believers.' The Prophet ﷺ said no Muslim calls with these words but Allah answers. Cast ashore weak, shaded by the gourd, he returned to a hundred thousand who believed. Lesson: tawhid in deepest darkness opens heaven's doors; despair never, and leaving the call without God's command is itself the trial."),
                step("زكريا عليه السلام", "Zechariah",
                    "كفل مريم بنت عمران وكان كلما دخل عليها المحراب وجد عندها رزقًا: يا مريم أنى لك هذا؟ قالت: هو من عند الله إن الله يرزق من يشاء بغير حساب.هنالك دعا زكريا ربه نداءً خفيًّا: رب هب لي من لدنك ذرية طيبة إنك سميع الدعاء.فنودي وهو قائم يصلي في المحراب: أن الله يبشرك بيحيى مصدقًا بكلمة من الله وسيدًا وحصورًا نبيًّا من الصالحين — قال: رب أنى يكون لي غلام وقد بلغني الكبر وامرأتي عاقر؟ قال: كذلك الله يفعل ما يشاء.وعبرته: الفرج من أضيق الأبواب — شيخ وامرأة عاقر ونداء خفي في جوف الليل؛ والكفالة الصالحة تفتح أبواب السماء لمربّيها.",
                    "Guardian of Mary, he found her provided for beyond nature: 'It is from Allah.' There he prayed in secret: 'Grant me good offspring.' Called while standing in prayer: 'Allah gives you glad tidings of Yahya' — 'How, when old age and a barren wife?' 'Allah does as He wills.' Lesson: relief comes through the narrowest doors — old age, barrenness, a whispered night prayer; and righteous guardianship opens heaven for the guardian."),
                step("يحيى عليه السلام", "John the Baptist",
                    "﴿يَا يَحْيَىٰ خُذِ الْكِتَابَ بِقُوَّةٍ ۖ وَآتَيْنَاهُ الْحُكْمَ صَبِيًّا﴾ [مريم: 12].أُعطي الحكم صبيًّا والحنان من لدننا وزكاة، وكان تقياً برًّا بوالديه ولم يكن جبارًا عصيًّا، وسيدًا وحصورًا ونبيًّا من الصالحين، وسلام عليه يوم ولد ويوم يموت ويوم يبعث حياً.ودعا إلى الله بصدقٍ حتى استُشهد في سبيل كلمته فيما رُوي بيد ظالم.وعبرته: أخذ الدين بالقوة والعزيمة منذ الصغر، وأن البرّ بالوالدين قرين النبوة، وأن كلمة الحق ثمنها غالٍ لكنها باقية.",
                    "'O Yahya, take the Book with strength' — given judgement while a child, tenderness and purity from Us, dutiful to his parents, no tyrant nor disobedient; peace the day he was born, the day he dies, the day he is raised (19:12-15). Tradition holds he was martyred for truth. Lesson: take religion with vigour from youth; kindness to parents accompanies prophethood; truth's price is high but it outlives tyrants."),
                step("عيسى عليه السلام — كلمة الله وروح منه", "Jesus",
                    "﴿إِنَّ مَثَلَ عِيسَىٰ عِندَ اللَّهِ كَمَثَلِ آدَمَ ۖ خَلَقَهُ مِن تُرَابٍ ثُمَّ قَالَ لَهُ كُن فَيَكُونُ﴾ [آل عمران: 59].بُوّبت به مريم العذراء بشرى من الله: يا مريم إن الله يبشرك بكلمة منه اسمه المسيح عيسى ابن مريم وجيهًا في الدنيا والآخرة ومن المقربين.قالت: رب أنى يكون لي ولد ولم يمسسني بشر؟ قال: كذلك الله يخلق ما يشاء.فمثل عيسى كمثل آدم: كلمة الله وروح منه — لا أب له كما أن آدم لا أب ولا أم.وتكلم في المهد: إني عبد الله آتاني الكتاب وجعلني نبيًّا وجعلني مباركًا أينما كنت وأوصاني بالصلاة والزكاة ما دمت حيًّا... والسلام عليّ يوم ولدت ويوم أموت ويوم أبعث حيًّا.وأيّده الله بمعجزات: يبرئ الأكمه والأبرص ويحيي الموتى بإذن الله وينفخ في الطين كهيئة الطير فيكون طيرًا بإذن الله، وأنزل عليه المائدة من السماء بطلب الحواريين، وأُنزل عليه الإنجيل هدى ونورًا.وأيده بالحواريين: من أنصاري إلى الله؟ قال الحواريون: نحن أنصار الله آمنا بالله واشهد بأننا مسلمون.ولم يُقتل ولم يُصلب: ﴿وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَٰكِن شُبِّهَ لَهُمْ﴾ [النساء: 157] — رفعه الله إليه وهو حيّ، وينزل آخر الزمان حكمًا عدلاً بشريعة محمد ﷺ فيكسر الصليب ويقتل الدجال ويُسلّم السلام — بشرى لأهل الكتاب المشتركة.وعبرته: قدرة الله لا تحدّها الأسباب، وعيسى عبد الله ورسوله لا أكثر ولا أقل، ورسالته رحمة وبرٌّ وإحياء للقلوب كما أحيا الموتى بإذن الله.",
                    "'The likeness of Jesus with Allah is as Adam: He created him from dust, then said Be, and he was' (3:59). Born of the virgin Mary by God's word — 'a spirit from Him' — he spoke in the cradle: 'I am the servant of Allah; He gave me the Book and made me a prophet.' His signs: healing the blind and leper, raising the dead by God's leave, the table from heaven, the Gospel's light. The disciples answered his call. He was neither killed nor crucified (4:157); Allah raised him, and he will return in the end-times with justice. Lesson: God's power is beyond causes; Jesus is Allah's servant and messenger — nothing more, nothing less."),
                step("محمد ﷺ — خاتم النبيين ورحمة العالمين", "Muhammad ﷺ — seal of the prophets",
                    "﴿مَّا كَانَ مُحَمَّدٌ أَبَا أَحَدٍ مِّن رِّجَالِكُمْ وَلَٰكِن رَّسُولَ اللَّهِ وَخَاتَمَ النَّبِيِّينَ﴾ [الأحزاب: 40].من ذرية إسماعيل بن إبراهيم، بُعث والناس في جاهلية عمياء فأخرجهم من الظلمات إلى النور، وأُنزل عليه القرآن المعجزة الخالدة المحفوظة، وبُعث رحمةً للعالمين: ﴿وَمَا أَرْسَلْنَاكَ إِلَّا رَحْمَةً لِّلْعَالَمِينَ﴾ [الأنبياء: 107].أكمل الناس خلقاً وعبادة وصدقاً وشجاعة ورحمة؛ أوتي جوامع الكلم، وأُنزلت عليه الشريعة الجامعة المهيمنة على ما قبلها، وأتم الله به الدين وأتمّ النعمة.ودعا إلى ما دعا إليه الأنبياء جميعًا: اعبدوا الله ما لكم من إله غيره، وشهد أن لا إله إلا الله وحده لا شريك له — كلمته هي كلمة كل نبي: ﴿وَلَقَدْ بَعَثْنَا فِي كُلِّ أُمَّةٍ رَّسُولًا أَنِ اعْبُدُوا اللَّهَ وَاجْتَنِبُوا الطَّاغُوتَ﴾ [النحل: 36].وبشر به عيسى: ﴿وَمُبَشِّرًا بِرَسُولٍ يَأْتِي مِن بَعْدِي اسْمُهُ أَحْمَدُ﴾ [الصف: 6]، وبشّر به إبراهيم دعاؤه، وسلامٌ عليه وعلى جميع إخوانه النبيين.وعبرة سيرته كلها: أن رجلاً واحدًا صادقًا صابرًا متوكلاً على الله يغيّر الله به وجه التاريخ — كما قال ربه: ﴿لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ لِّمَن كَانَ يَرْجُو اللَّهَ وَالْيَوْمَ الْآخِرَ وَذَكَرَ اللَّهَ كَثِيرًا﴾ [الأحزاب: 21].",
                    "'Muhammad is not the father of any of your men, but the Messenger of Allah and the seal of the prophets' (33:40). Of Ishmael's line, sent to a world in deepest darkness, given the ever-preserved Qur'an, dispatched purely as mercy to all worlds (21:107). The most complete in character, devotion, truthfulness and courage; his law crowns all before it. He called to what every prophet called: worship Allah, avoid false gods — Jesus himself heralded him as Ahmad (61:6). His whole life's lesson: one truthful, patient, God-reliant man can change history's face — 'in the Messenger of Allah you have an excellent example' (33:21)."),
            ),
        )
    }

    private fun step(
        titleAr: String,
        titleEn: String,
        detailAr: String,
        detailEn: String,
    ): LearnStep = LearnStep(titleAr, titleEn, detailAr, detailEn)
}
